<script setup>import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanForm from '../../../components/admin/plans/PlanForm.vue';const route=useRoute(),router=useRouter(),plan=ref(null),error=ref(null),busy=ref(false);onMounted(async()=>{try{plan.value=(await api.get('/v1/platform/plans/'+route.params.id)).data.data}catch(e){error.value=e}});async function submit(data){busy.value=true;error.value=null;try{await api.put('/v1/platform/plans/'+route.params.id,data);await router.push({name:'admin.plans.show',params:{id:route.params.id},query:{updated:1}})}catch(e){error.value=e}finally{busy.value=false}}</script>
<template><div><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.plans.show',params:{id:route.params.id}}">Back to Plan</RouterLink><h1 class="mt-3">Edit Subscription Plan</h1><p>Changes apply to future provisioning. Existing subscription limit snapshots remain unchanged.</p></div></header><FormErrors :error="error"/><p v-if="!plan&&!error" class="loading-state">Loading plan...</p><PlanForm v-if="plan" :initial="plan" submit-label="Save Plan" :busy="busy" @submit="submit" @cancel="router.back()"/></div></template>
